import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function LoginForm({ setIsAuthenticated }) {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setErrors({});
    setMessage('');

    try {
      const response = await fetch('http://127.0.0.1:8000/api/login', {
        method: 'POST',
        credentials: 'include', // Добавлено для работы с Sanctum
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      const data = await response.json();

      if (!response.ok) {
        // Обработка ошибок валидации (422) и других ошибок
        if (response.status === 422) {
          setErrors(data.errors || {});
        }
        throw new Error(data.message || 'Ошибка входа');
      }

      // Успешная авторизация
      localStorage.setItem('authToken', data.token);
      setIsAuthenticated(true);
      navigate('/dashboard', { replace: true });

    } catch (error) {
      setMessage(error.message || 'Ошибка соединения с сервером');
      console.error('Login error:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Очищаем ошибку при изменении поля
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>Email:</label>
        <input
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          required
          autoComplete="username"
        />
        {errors?.email && <div className="error">{errors.email[0]}</div>}
      </div>

      <div>
        <label>Пароль:</label>
        <input
          type="password"
          name="password"
          value={formData.password}
          onChange={handleChange}
          required
          autoComplete="current-password"
        />
        {errors?.password && <div className="error">{errors.password[0]}</div>}
      </div>

      <button 
        type="submit" 
        disabled={isLoading}
        aria-busy={isLoading}
      >
        {isLoading ? 'Вход...' : 'Войти'}
      </button>

      {message && (
        <div className={`message ${errors ? 'error' : ''}`}>
          {message}
        </div>
      )}
    </form>
  );
}

export default LoginForm;
